from pathlib import Path
import base64, hashlib, io, json, zipfile
from html.parser import HTMLParser
root=Path('products')
out=root/'distribution'
out.mkdir(parents=True,exist_ok=True)
class Text(HTMLParser):
 def __init__(self): super().__init__(); self.parts=[]
 def handle_data(self,data):
  if data.strip(): self.parts.append(data.strip())
report={'publication_status':'not submitted','revenue_verified':False,'price_status':'USD 49 is an unvalidated proposed price','constraints':['Hosting credentials are absent according to existing evidence.','Public listing requires independent approval of the exact artifact.','No authenticated submission capability has been established.']}
try:
 encoded=(out/'invoice-preflight-review.zip.base64.txt').read_text()
 data=base64.b64decode(''.join(encoded.split()),validate=True)
 with zipfile.ZipFile(io.BytesIO(data)) as archive:
  bad=archive.testzip()
  if bad: raise ValueError('Archive integrity failure: '+bad)
  report['bundle']={'sha256':hashlib.sha256(data).hexdigest(),'files':archive.namelist(),'integrity':'passed'}
except Exception as exc:
 report['bundle']={'integrity':'failed','error':str(exc)}
for name,path in [('idea_verdict',root/'research/invoice-idea-verdict.json'),('manifest',out/'bundle-manifest.json')]:
 try: report[name]=json.loads(path.read_text())
 except Exception as exc: report[name]={'read_error':str(exc)}
try:
 parser=Text(); parser.feed((root/'research/show-hn-guidelines.html').read_text())
 report['channel_rules']={'url':'https://news.ycombinator.com/showhn.html','source_text':parser.parts,'status':'retrieved; eligibility requires review before submission'}
except Exception as exc:
 report['channel_rules']={'status':'unverified','error':str(exc)}
draft='''DRAFT — NOT SUBMITTED

Candidate channel: Show HN
Rules source: https://news.ycombinator.com/showhn.html
Eligibility is pending review of the saved rules and a publicly accessible demo.

Proposed title: Show HN: An offline CSV structure checker

I built a small offline CSV structure checker. It is a generic prototype; real accounting-platform imports and Manager.io compatibility have not been verified. The source and current test evidence must accompany the demo. This product is made by autonomous AI agents.

I am testing whether invoice-import users need a checker tailored to their workflow. If this is relevant, which CSV structure problem blocks your import? Please describe it without sharing private customer or invoice data.

A proposed fixed-scope customization would cost USD 49, subject to agreeing on a sample format, supported checks and delivery criteria. This is a price experiment; payment collection is not available.

Experiment: After an eligible, independently approved demo is actually published and this post is permitted and submitted, observe responses for seven days. Record the exact submission URL, observation times, substantive workflow descriptions and explicit interest at the proposed price. Success threshold: three distinct users describe a concrete import problem and at least one explicitly expresses interest at USD 49. Views alone do not establish willingness to pay. No response is not interpretable without exposure evidence.

Launch gate: archive integrity passes; the saved idea verdict permits this experiment; claims match inspected artifacts; current channel rules permit submission; a public demo and authenticated submission access exist; independent approval covers the exact public artifact. Do not submit this draft until those conditions are verified.
'''
(out/'show-hn-demand-experiment.txt').write_text(draft)
report['next_constraint']='Obtain one permitted public distribution route for the reviewed demo; do not repeat absent hosting credential probes.'
(out/'demand-experiment-readiness.json').write_text(json.dumps(report,indent=2))
print(json.dumps({'bundle':report['bundle'],'draft':'products/distribution/show-hn-demand-experiment.txt','submitted':False}))
